impl Body {
    #[effects(alloc)]
    fn method_target(self: &mut Body, cx: &FnCtx, rt: &ast::TypeKind, recv: &ast::Expr, name: &ast::Ident, args: &[ast::Expr], span: source::Span) -> Found {
        let value: ast::TypeKind = match ref_inner(rt) {
            None => rt.clone(),
            Some(inner) => inner,
        };
        let tp: String = match types::named_path(&value) {
            None => String::new(),
            Some(p) => p,
        };
        let user_type: bool = is_named(&value) && self.c.adts.has(tp.as_str());
        if user_type {
            match self.c.fns.find(types::cat3(tp.as_str(), "::", name.name.as_str()).as_str()) {
                None => {},
                Some(at) => { let sig: types::FnSig = self.c.fns.items[at].clone(); if no_text(&sig.trait_of) { return self.bind_method(cx, rt, &value, tp.as_str(), false, &sig, recv, name, args, span); } },
            }
        }
        if text_kind(&value) && !builtin_method_name(name.name.as_str()) {
            match self.c.fns.find(types::cat2("std::str::", name.name.as_str()).as_str()) {
                None => {},
                Some(at) => { if self.c.fns.items[at].generics.len() == 0 && self.c.fns.items[at].params.len() > 0 && is_text(&self.c.fns.items[at].params[0]) { let mut path: Vec<String> = Vec::new(); path.push(String::from("std")); path.push(String::from("str")); path.push(name.name.clone()); let adjust: ast::Adjust = if is_str(&value) { ast::Adjust::Value } else { ast::Adjust::AsStr }; let none: Vec<ast::TypeKind> = Vec::new(); return Found::Target(MethodTarget { path: path, type_args: none, adjust: adjust }); } },
            }
        }
        let mut traits: Vec<String> = Vec::new();
        let by_param: bool = types::is_param(&value);
        match types::param_name(&value) {
            None => { if !user_type && builtin_method_name(name.name.as_str()) { return Found::No; } if types::is_error(&value) || is_never(&value) { return Found::No; } for i in 0..self.c.trait_impls.len() invariant 0 <= i && i <= self.c.trait_impls.len(), { if impl_matches(&self.c.trait_impls[i], &value) { traits.push(self.c.trait_impls[i].trait_path.clone()); } } for j in 0..self.c.rejected_impls.len() invariant 0 <= j && j <= self.c.rejected_impls.len(), { if impl_matches(&self.c.rejected_impls[j], &value) { traits.push(self.c.rejected_impls[j].trait_path.clone()); } } },
            Some(p) => { for i in 0..self.c.tparams.len() invariant 0 <= i && i <= self.c.tparams.len(), { if self.c.tparams[i].name == p { for j in 0..self.c.tparams[i].bounds.len() invariant 0 <= j && j <= self.c.tparams[i].bounds.len(), { traits.push(self.c.tparams[i].bounds[j].clone()); } } } },
        }
        let mut having: Vec<String> = Vec::new();
        for i in 0..traits.len()
            invariant 0 <= i && i <= traits.len(),
        {
            match self.c.traits.find(traits[i].as_str()) {
                None => {},
                Some(at) => { if types::has(self.c.traits.items[at].methods.as_slice(), name.name.as_str()) { having.push(traits[i].clone()); } },
            }
        }
        let with: Vec<String> = sorted_set(having.as_slice());
        if with.len() == 0 {
            if user_type || by_param {
                self.unknown_method(cx, &value, name, traits.as_slice());
                return Found::Reported;
            }
            return Found::No;
        }
        if with.len() == 1 {
            return match self.c.fns.find(types::cat3(with[0].as_str(), "::", name.name.as_str()).as_str()) { None => Found::No, Some(at) => { let sig: types::FnSig = self.c.fns.items[at].clone(); self.bind_method(cx, rt, &value, with[0].as_str(), true, &sig, recv, name, args, span) }, };
        }
        let mut shown: Vec<String> = Vec::new();
        for i in 0..with.len()
            invariant 0 <= i && i <= with.len(),
        {
            shown.push(variant_text(with[i].as_str(), name.name.as_str(), cx.mod_path.as_str()));
        }
        let first: String = if shown.len() > 0 {
            shown[0].clone()
        } else {
            String::new()
        };
        Found::Reported
    }
}

#[effects(alloc)]
fn pass_item(st: &mut State, full: &str, single: bool, aspan: source::Span, gp: &str, gi: usize, b: usize, j: usize, by_ref: bool, todo: &mut Vec<Todo>) -> () {
    if gi >= st.generics.items.len() || b >= st.generics.items[gi].bounded.len() {
        return;
    }
    let k: usize = st.generics.items[gi].bounded[b].k;
    let mut h: String = String::new();
    match resolve(&st.generics, &st.items, full, single, st.unit.as_str()) {
        None => { return; },
        Some(r) => { h = r; },
    }
    let mut hi: usize = 0;
    match st.items.find(h.as_str()) {
        None => { return; },
        Some(i) => { hi = i; },
    }
    if hi >= st.items.items.len() {
        return;
    }
    let mut tr: String = st.generics.items[gi].unit.clone();
    tr.push_str("::");
    push_trait_name(&mut tr, st.generics.items[gi].order, k);
    let mut key: String = h.clone();
    key.push_str("\0");
    key.push_str(tr.as_str());
    let have: Vec<String> = effect_set(st.items.items[hi].effects.as_str());
    let allowed: Vec<String> = effect_set(st.generics.items[gi].effects.as_str());
    let mut extra: Vec<String> = Vec::new();
    for e in 0..have.len() {
        if !has(allowed.as_slice(), have[e].as_str()) {
            extra.push(have[e].clone());
        }
    }
    let reported: bool = extra.len() > 0;
    let hn: String = last_seg(h.as_str());
    if reported {
        let mut msg: String = String::from("`");
        msg.push_str(hn.as_str());
        msg.push_str("` has effect `");
        push_joined(&mut msg, extra.as_slice(), ", ");
        msg.push_str("`, which `");
        msg.push_str(gp);
        msg.push_str("` does not declare for its `");
        msg.push_str(st.generics.items[gi].bounded[b].name.as_str());
        msg.push_str("`");
        let mut fx: String = String::from("declare `");
        push_joined(&mut fx, extra.as_slice(), ", ");
        fx.push_str("` on `");
        fx.push_str(gp);
        fx.push_str("`, or pass a function without it");
    }
    let mut sname: String = String::new();
    match st.made.find(key.as_str()) {
        None => { let mut short: String = String::from("__fnitem$"); std::num::push_u64(&mut short, st.items_made as u64); st.items_made = st.items_made.saturating_add(1); let mut path: String = st.items.items[hi].unit.clone(); path.push_str("::"); path.push_str(short.as_str()); st.names.insert(path.as_str(), h.clone()); let mut typed: String = String::new(); let mut a: String = String::new(); for q in 0..st.items.items[hi].params.len() { typed.push_str(", "); typed.push_str(st.items.items[hi].params[q].name.as_str()); typed.push_str(": "); typed.push_str(st.items.items[hi].params[q].ty.as_str()); if q > 0 { a.push_str(", "); } a.push_str(st.items.items[hi].params[q].name.as_str()); } let mut body: String = hn.clone(); body.push_str("("); body.push_str(a.as_str()); body.push_str(")"); let mut t: String = String::new(); impl_text(&mut t, short.as_str(), "", tr.as_str(), typed.as_str(), st.items.items[hi].ret_name.as_str(), st.items.items[hi].ret.as_str(), conj(st.items.items[hi].pre.as_slice()).as_str(), conj(st.items.items[hi].post.as_slice()).as_str(), st.items.items[hi].effects.as_str(), &st.generics.items[gi].bounded[b].bound.kind, a.as_str(), body.as_str()); let unit: String = st.items.items[hi].unit.clone(); push_text(&mut st.text, unit.as_str(), reported, t.as_str()); let isp: source::Span = st.items.items[hi].span; locate(&mut st.located, path.as_str(), tr.as_str(), isp); st.made.insert(key.as_str(), path.clone()); sname = path; },
        Some(mi) => { sname = st.made.items[mi].clone(); },
    }
    st.passes.push(Pass { span: aspan, what: h });
    todo.push(Todo { j: j, sname: sname, k: k, by_ref: by_ref, caps: Vec::new() });
}

