            return Some(ast::Expr { kind: ast::ExprKind::Error, span: mspan });
        }
        let mut path: Vec<ast::Ident> = self.relative_path_prefix();
        path.push(self.ident("name")?);
        let mut targs: Vec<ast::TArgs> = Vec::new();
        let mut n: usize = self.left();
        while n > 0 && self.is_p("::")
            decreases n,
        {
            n = n - 1;
            let colons: source::Span = self.bump();
            if self.is_p("<") {
                let targ: Vec<ast::Type> = self.parse_type_args(d);
                targs.push(ast::TArgs { seg: path.len().saturating_sub(1), args: targ, span: colons.to(self.prev_span()) });
            } else {
                path.push(self.ident("path segment")?);
            }
        }
        if targs.len() > 0 && !self.is_p("(") {
            self.err("E0301", targs[0].span, "type arguments are written only on calls: `f::<T>(..)`");
        }
        if self.is_p("(") {
            let args: Vec<ast::Expr> = self.parse_args(d)?;
            return Some(ast::Expr { kind: ast::ExprKind::Call(ast::Call { path: path, targs: targs, args: args, method: None }), span: lo.to(self.prev_span()) });
        }
        let capital: bool = path.len() > 0 && upper_first(path[path.len() - 1].name.as_str());
        let habit: bool = !self.no_struct && capital && (self.t.is_p(1, "..") || self.t.kind(1) == 0 && (self.t.is_p(2, ",") || self.t.is_p(2, "}")));
        if self.is_p("{") && (habit || self.t.kind(1) == 0 && self.t.is_p(2, ":")) {
            self.bump();
            let mut fields: Vec<ast::FieldInit> = Vec::new();
            let mut rest: Option<Box<ast::Expr>> = None;
            let mut m: usize = self.left();
            while m > 0 && !self.is_p("}")
                decreases m,
            {
                m = m - 1;
                if self.eat_p("..") {
                    rest = Some(Box::new(self.parse_expr(d)?));
                    m = 0;
                } else {
                    let fname: ast::Ident = self.ident("field name")?;
                    if self.eat_p(":") {
                        let fv: ast::Expr = self.parse_expr(d)?;
                        fields.push(ast::FieldInit { name: fname, value: fv });
                    } else {
                        let mut r: String = fname.name.clone();
                        r.push_str(": ");
                        r.push_str(fname.name.as_str());
                        self.diags.push(diag::fix(diag::new("E0222", fname.span, cat3("field shorthand `", fname.name.as_str(), "` is not allowed").as_str()), tick_write(r.as_str()).as_str(), Some(r)));
                        let sv: ast::Expr = ast::Expr { kind: ast::ExprKind::Var(ast::Ident { name: fname.name.clone(), span: fname.span }), span: fname.span };
                        fields.push(ast::FieldInit { name: fname, value: sv });
                    }
                    if !self.eat_p(",") {
                        m = 0;
                    }
                }
            }
            let shi: source::Span = self.expect_p("}")?;
            return Some(ast::Expr { kind: ast::ExprKind::StructLit(ast::StructLit { path: path, fields: fields, rest: rest }), span: lo.to(shi) });
        }
        if path.len() > 1 {
            let pspan: source::Span = lo.to(self.prev_span());
            return Some(ast::Expr { kind: ast::ExprKind::Path(path), span: pspan });
        }
        let id: ast::Ident = path.pop()?;
        let ispan: source::Span = id.span;
        Some(ast::Expr { kind: ast::ExprKind::Var(id), span: ispan })
    }
}

impl Body {
    #[effects(alloc)]
    fn method_target(self: &mut Body, cx: &FnCtx, rt: &ast::TypeKind, recv: &ast::Expr, name: &ast::Ident, args: &[ast::Expr], span: source::Span) -> Found {
        let value: ast::TypeKind = match ref_inner(rt) {
            None => rt.clone(),
            Some(inner) => inner,
        };
        let tp: String = match types::named_path(&value) {
            None => String::new(),
            Some(p) => p,
        };
        let user_type: bool = is_named(&value) && self.c.adts.has(tp.as_str());
        if user_type {
            match self.c.fns.find(types::cat3(tp.as_str(), "::", name.name.as_str()).as_str()) {
                None => {},
                Some(at) => { let sig: types::FnSig = self.c.fns.items[at].clone(); if no_text(&sig.trait_of) { return self.bind_method(cx, rt, &value, tp.as_str(), false, &sig, recv, name, args, span); } },
            }
        }
        if text_kind(&value) && !builtin_method_name(name.name.as_str()) {
            match self.c.fns.find(types::cat2("std::str::", name.name.as_str()).as_str()) {
                None => {},
                Some(at) => { if self.c.fns.items[at].generics.len() == 0 && self.c.fns.items[at].params.len() > 0 && is_text(&self.c.fns.items[at].params[0]) { let mut path: Vec<String> = Vec::new(); path.push(String::from("std")); path.push(String::from("str")); path.push(name.name.clone()); let adjust: ast::Adjust = if is_str(&value) { ast::Adjust::Value } else { ast::Adjust::AsStr }; let none: Vec<ast::TypeKind> = Vec::new(); return Found::Target(MethodTarget { path: path, type_args: none, adjust: adjust }); } },
            }
        }
        let mut traits: Vec<String> = Vec::new();
        let by_param: bool = types::is_param(&value);
        match types::param_name(&value) {
            None => { if !user_type && builtin_method_name(name.name.as_str()) { return Found::No; } if types::is_error(&value) || is_never(&value) { return Found::No; } for i in 0..self.c.trait_impls.len() invariant 0 <= i && i <= self.c.trait_impls.len(), { if impl_matches(&self.c.trait_impls[i], &value) { traits.push(self.c.trait_impls[i].trait_path.clone()); } } for j in 0..self.c.rejected_impls.len() invariant 0 <= j && j <= self.c.rejected_impls.len(), { if impl_matches(&self.c.rejected_impls[j], &value) { traits.push(self.c.rejected_impls[j].trait_path.clone()); } } },
            Some(p) => { for i in 0..self.c.tparams.len() invariant 0 <= i && i <= self.c.tparams.len(), { if self.c.tparams[i].name == p { for j in 0..self.c.tparams[i].bounds.len() invariant 0 <= j && j <= self.c.tparams[i].bounds.len(), { traits.push(self.c.tparams[i].bounds[j].clone()); } } } },
        }
        let mut having: Vec<String> = Vec::new();
        for i in 0..traits.len()
            invariant 0 <= i && i <= traits.len(),
        {
            match self.c.traits.find(traits[i].as_str()) {
                None => {},
                Some(at) => { if types::has(self.c.traits.items[at].methods.as_slice(), name.name.as_str()) { having.push(traits[i].clone()); } },
            }
        }
        let with: Vec<String> = sorted_set(having.as_slice());
        if with.len() == 0 {
            if user_type || by_param {
                self.unknown_method(cx, &value, name, traits.as_slice());
                return Found::Reported;
            }
            return Found::No;
        }
        if with.len() == 1 {
            return match self.c.fns.find(types::cat3(with[0].as_str(), "::", name.name.as_str()).as_str()) { None => Found::No, Some(at) => { let sig: types::FnSig = self.c.fns.items[at].clone(); self.bind_method(cx, rt, &value, with[0].as_str(), true, &sig, recv, name, args, span) }, };
        }
        let mut shown: Vec<String> = Vec::new();
        for i in 0..with.len()
            invariant 0 <= i && i <= with.len(),
        {
            shown.push(variant_text(with[i].as_str(), name.name.as_str(), cx.mod_path.as_str()));
        }
        let first: String = if shown.len() > 0 {
            shown[0].clone()
        } else {
            String::new()
        };
        self.c.help("E0313", name.span, types::cat7("`", name.name.as_str(), "` is a method of more than one trait of `", types::text_in(&value, cx.mod_path.as_str()).as_str(), "`: `", types::join(shown.as_slice(), "`, `").as_str(), "`").as_str(), types::cat3("call the one you mean by path: `", first.as_str(), "(..)`").as_str());
        Found::Reported
    }
}

#[effects(alloc)]
fn maybe_moved(m: &mut Mv, name: &str, span: source::Span, how: &str) -> () {
    m.diags.push(diag::fix(diag::new("E0414", span, types::cat4("`", name, "` is moved ", how).as_str()), types::cat3("move or assign `", name, "` on every path: an owned value is dropped at a point fixed by the program text (ADR-0031 §2)").as_str(), None));
}

#[effects(alloc)]
fn pass_item(st: &mut State, full: &str, single: bool, aspan: source::Span, gp: &str, gi: usize, b: usize, j: usize, by_ref: bool, todo: &mut Vec<Todo>) -> () {
    if gi >= st.generics.items.len() || b >= st.generics.items[gi].bounded.len() {
        return;
    }
    let k: usize = st.generics.items[gi].bounded[b].k;
    let mut h: String = String::new();
    match resolve(&st.generics, &st.items, full, single, st.unit.as_str()) {
        None => { return; },
        Some(r) => { h = r; },
    }
    let mut hi: usize = 0;
    match st.items.find(h.as_str()) {
        None => { return; },
        Some(i) => { hi = i; },
    }
    if hi >= st.items.items.len() {
        return;
    }
    let mut tr: String = st.generics.items[gi].unit.clone();
    tr.push_str("::");
    push_trait_name(&mut tr, st.generics.items[gi].order, k);
    let mut key: String = h.clone();
    key.push_str("\0");
    key.push_str(tr.as_str());
    let have: Vec<String> = effect_set(st.items.items[hi].effects.as_str());
    let allowed: Vec<String> = effect_set(st.generics.items[gi].effects.as_str());
    let mut extra: Vec<String> = Vec::new();
    for e in 0..have.len() {
        if !has(allowed.as_slice(), have[e].as_str()) {
            extra.push(have[e].clone());
        }
    }
    let reported: bool = extra.len() > 0;
    let hn: String = last_seg(h.as_str());
    if reported {
        let mut msg: String = String::from("`");
        msg.push_str(hn.as_str());
        msg.push_str("` has effect `");
        push_joined(&mut msg, extra.as_slice(), ", ");
        msg.push_str("`, which `");
        msg.push_str(gp);
        msg.push_str("` does not declare for its `");
        msg.push_str(st.generics.items[gi].bounded[b].name.as_str());
        msg.push_str("`");
        let mut fx: String = String::from("declare `");
        push_joined(&mut fx, extra.as_slice(), ", ");
        fx.push_str("` on `");
        fx.push_str(gp);
        fx.push_str("`, or pass a function without it");
        st.pending.push(diag::fix(diag::new("E0608", aspan, msg.as_str()), fx.as_str(), None));
    }
    let mut sname: String = String::new();
    match st.made.find(key.as_str()) {
        None => { let mut short: String = String::from("__fnitem$"); std::num::push_u64(&mut short, st.items_made as u64); st.items_made = st.items_made.saturating_add(1); let mut path: String = st.items.items[hi].unit.clone(); path.push_str("::"); path.push_str(short.as_str()); st.names.insert(path.as_str(), h.clone()); let mut typed: String = String::new(); let mut a: String = String::new(); for q in 0..st.items.items[hi].params.len() { typed.push_str(", "); typed.push_str(st.items.items[hi].params[q].name.as_str()); typed.push_str(": "); typed.push_str(st.items.items[hi].params[q].ty.as_str()); if q > 0 { a.push_str(", "); } a.push_str(st.items.items[hi].params[q].name.as_str()); } let mut body: String = hn.clone(); body.push_str("("); body.push_str(a.as_str()); body.push_str(")"); let mut t: String = String::new(); impl_text(&mut t, short.as_str(), "", tr.as_str(), typed.as_str(), st.items.items[hi].ret_name.as_str(), st.items.items[hi].ret.as_str(), conj(st.items.items[hi].pre.as_slice()).as_str(), conj(st.items.items[hi].post.as_slice()).as_str(), st.items.items[hi].effects.as_str(), &st.generics.items[gi].bounded[b].bound.kind, a.as_str(), body.as_str()); let unit: String = st.items.items[hi].unit.clone(); push_text(&mut st.text, unit.as_str(), reported, t.as_str()); let isp: source::Span = st.items.items[hi].span; locate(&mut st.located, path.as_str(), tr.as_str(), isp); st.made.insert(key.as_str(), path.clone()); sname = path; },
        Some(mi) => { sname = st.made.items[mi].clone(); },
    }
    st.passes.push(Pass { span: aspan, what: h });
    todo.push(Todo { j: j, sname: sname, k: k, by_ref: by_ref, caps: Vec::new() });
}

impl Parser {
    #[effects(alloc)]
    fn parse_fn(self: &mut Parser, attrs: Vec<ast::Attr>, d: usize) -> Option<ast::FnDef>
        requires d <= 256,
    {
        let lo: source::Span = self.span();
        let kind: ast::FnKind = if self.eat_kw("spec") {
            ast::FnKind::Spec
        } else if self.eat_kw("proof") {
            ast::FnKind::Proof
        } else {
            ast::FnKind::Exec
        };
        let is_proof: bool = match &kind {
            ast::FnKind::Exec => false,
            ast::FnKind::Spec => false,
            ast::FnKind::Proof => true,
        };
        self.bump();
        let name: ast::Ident = self.ident("function name")?;
        let mut generics: Vec<ast::TypeParam> = self.parse_generics(d);
        self.expect_p("(")?;
        let mut params: Vec<ast::Param> = Vec::new();
        let mut n: usize = self.left();
        while n > 0 && !self.is_p(")")
            decreases n,
        {
            n = n - 1;
            if self.is_kw("mut") {
                let msp: source::Span = self.bump();
                self.err_rep("E0210", msp, "`mut` parameters are not allowed", "copy into a `let mut` local inside the body", "");
            }
            let amp: bool = self.is_p("&");
            let short: bool = amp && self.t.is_kw(1, "self") || amp && self.t.is_kw(1, "mut") && self.t.is_kw(2, "self") || self.is_kw("self") && !self.t.is_p(1, ":");
            if short {
                let slo: source::Span = self.span();
                let form: u8 = if amp && self.t.is_kw(1, "mut") {
                    2
                } else if amp {
                    1
                } else {
                    0
                };
                let mut k: usize = self.left();
                while k > 0 && !self.is_kw("self")
                    decreases k,
                {
                    k = k - 1;
                    self.bump();
                }
                let sp: source::Span = slo.to(self.bump());
                let d0: diag::Diag = diag::new("E0228", sp, "the receiver needs its type");
                let mut pkind: ast::TypeKind = ast::TypeKind::Error;
                match &self.impl_ty {
                    None => self.diags.push(diag::fix(d0, "write `self: &T`, `self: &mut T` or `self: T` with the `impl` type", None)),
                    Some(t) => { let mut one: Vec<String> = Vec::new(); one.push(t.clone()); let named: ast::Type = ast::Type { kind: ast::TypeKind::Named(one, Vec::new()), span: sp }; let mut r: String = String::from("self: "); if form == 2 { r.push_str("&mut "); } else if form == 1 { r.push_str("&"); } r.push_str(t.as_str()); if form == 0 { pkind = named.kind; } else { pkind = ast::TypeKind::Ref(form == 2, Box::new(named)); } self.diags.push(diag::fix(d0, tick_write(r.as_str()).as_str(), Some(r))); },
                }
                params.push(ast::Param { name: ast::Ident { name: String::from("self"), span: sp }, ty: ast::Type { kind: pkind, span: sp } });
                if !self.eat_p(",") {
                    n = 0;
                }
            } else {
                let pname: ast::Ident = if self.is_kw("self") {
                    ast::Ident { name: String::from("self"), span: self.bump() }
                } else {
                    self.ident("parameter name")?
                };
                self.expect_p(":")?;
                let pty: ast::Type = self.parse_type(d);
                params.push(ast::Param { name: pname, ty: pty });
                if !self.eat_p(",") {
                    n = 0;
                }
            }
        }
        self.expect_p(")")?;
        let gspan2: Option<source::Span> = self.generics_span;
        let mut ret: ast::Ret = ast::Ret { name: None, ty: ast::Type { kind: ast::TypeKind::Unit, span: self.prev_span() } };
        if is_proof {
            if self.is_p("->") {
                let alo: source::Span = self.span();
                self.bump();
                self.parse_ret(d)?;
                self.err_rep_to("E0256", alo, "a `proof fn` has no return type: what it proves is its `ensures`", "remove the return type", "");
            }
        } else if self.eat_p("->") {
            ret = self.parse_ret(d)?;
        } else {
            let nsp: source::Span = self.prev_span();
            self.err_rep("E0209", nsp, "function return type is required", "add `-> ()`", ") -> ()");
        }
        self.parse_where(&mut generics, gspan2, d);
        let cl: Clauses = self.parse_clauses(d)?;
        let mut body: ast::Block = ast::Block { stmts: Vec::new(), tail: None, span: self.span() };
        if self.decl_ok && self.is_p(";") {
            self.bump();
        } else {
            self.decl_ok = false;
            body = self.parse_block(d)?;
        }
        let span: source::Span = lo.to(body.span);
        Some(ast::FnDef { kind: kind, name: name, generics: generics, attrs: attrs, params: params, ret: ret, pre: cl.pre, post: cl.post, measure: cl.measure, body: body, span: span })
    }
}

#[effects(alloc)]
fn render(d: &Diag, sm: &source::SourceMap) -> String {
    let a: source::Pos = sm.line_col(d.span.file, d.span.lo);
    let b: source::Pos = sm.line_col(d.span.file, d.span.hi);
    let mut s: String = String::from("{\"code\":");
    std::json::push_string(&mut s, d.code.as_str());
    s.push_str(",\"sev\":\"");
    push_severity(&mut s, d.code.as_str());
    s.push_str("\",\"message\":");
    std::json::push_string(&mut s, d.message.as_str());
    s.push_str(",\"file\":");
    sm.push_name(&mut s, d.span.file);
    s.push_str(",\"line\":");
    std::num::push_u64(&mut s, a.line as u64);
    s.push_str(",\"col\":");
    std::num::push_u64(&mut s, a.col as u64);
    s.push_str(",\"end_line\":");
    std::num::push_u64(&mut s, b.line as u64);
    s.push_str(",\"end_col\":");
    std::num::push_u64(&mut s, b.col as u64);
    match &d.obligation {
        None => {},
        Some(o) => { s.push_str(",\"obligation\":"); std::json::push_string(&mut s, o.as_str()); },
    }
    match &d.bounded {
        None => {},
        Some(k) => { s.push_str(",\"bounded\":{\"b\":"); std::num::push_i64(&mut s, k.b); s.push_str(",\"l\":"); std::num::push_u64(&mut s, k.l as u64); s.push_str("}"); },
    }
    match &d.fix {
        None => {},
        Some(f) => { s.push_str(",\"fix\":{\"message\":"); std::json::push_string(&mut s, f.message.as_str()); match &f.replacement { None => {}, Some(r) => { s.push_str(",\"replacement\":"); std::json::push_string(&mut s, r.as_str()); }, } s.push_str("}"); },
    }
    s.push_str("}");
    s
}

